package com.gittexplorer.documentextractor.service.impl;
import com.gittexplorer.documentextractor.dto.DocumentExtractionResponse;import com.gittexplorer.documentextractor.exception.DocumentExtractionException;import com.gittexplorer.documentextractor.extractor.TextExtractionService;import com.gittexplorer.documentextractor.model.DocumentStatus;import com.gittexplorer.documentextractor.service.DocumentService;import com.gittexplorer.documentextractor.service.RegexExtractionService;import com.gittexplorer.documentextractor.util.FileNameUtility;import com.gittexplorer.documentextractor.util.HashUtility;import com.gittexplorer.documentextractor.validation.FileValidationService;import java.io.IOException;import java.time.Instant;import java.util.List;import java.util.UUID;import java.util.concurrent.CompletableFuture;import java.util.concurrent.Executor;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.stereotype.Service;import org.springframework.web.multipart.MultipartFile;
@Service public class DocumentServiceImpl implements DocumentService { private static final Logger log=LoggerFactory.getLogger(DocumentServiceImpl.class); private final FileValidationService validation; private final TextExtractionService extractor; private final RegexExtractionService regex; private final HashUtility hash; private final FileNameUtility names; private final Executor executor; public DocumentServiceImpl(FileValidationService validation,TextExtractionService extractor,RegexExtractionService regex,HashUtility hash,FileNameUtility names,@Qualifier("documentTaskExecutor") Executor executor){this.validation=validation;this.extractor=extractor;this.regex=regex;this.hash=hash;this.names=names;this.executor=executor;} public DocumentExtractionResponse extract(MultipartFile[] files){long started=System.nanoTime();String requestId=UUID.randomUUID().toString();validation.validate(files);long total=java.util.Arrays.stream(files).mapToLong(MultipartFile::getSize).sum();for (MultipartFile file : files) { validateSupportedType(file); }log.info("requestId={} documents={} totalUploadSize={}",requestId,files.length,total);List<DocumentExtractionResponse.DocumentResult> docs=java.util.Arrays.stream(files).map(f->CompletableFuture.supplyAsync(()->process(requestId,f),executor)).map(CompletableFuture::join).toList();long ok=docs.stream().filter(d->DocumentStatus.SUCCESS.name().equals(d.status())).count();long elapsed=(System.nanoTime()-started)/1_000_000;var summary=new DocumentExtractionResponse.Summary(files.length,docs.size(),(int)ok,docs.size()-(int)ok,total,elapsed);return new DocumentExtractionResponse(requestId,Instant.now(),summary,docs);} private void validateSupportedType(MultipartFile file){try{String fileName=names.safeName(file.getOriginalFilename());validation.validateSupported(fileName,extractor.detectMimeType(file.getBytes(),fileName));}catch(IOException ex){throw new com.gittexplorer.documentextractor.exception.InvalidUploadException("Unable to read uploaded file: "+file.getOriginalFilename());}} private DocumentExtractionResponse.DocumentResult process(String requestId,MultipartFile file){long started=System.nanoTime();String fileName=names.safeName(file.getOriginalFilename());try{byte[] bytes=file.getBytes();String mime=extractor.detectMimeType(bytes,fileName);validation.validateSupported(fileName,mime);String text=extractor.extract(bytes,fileName);long elapsed=(System.nanoTime()-started)/1_000_000;log.info("requestId={} file={} size={} durationMs={} status=SUCCESS",requestId,fileName,file.getSize(),elapsed);return new DocumentExtractionResponse.DocumentResult(fileName,mime,names.extensionOf(fileName),file.getSize(),hash.sha256(bytes),Instant.now(),text.length(),elapsed,DocumentStatus.SUCCESS.name(),text,regex.extractIdentifiers(text),null);}catch(Exception ex){long elapsed=(System.nanoTime()-started)/1_000_000;String message=ex instanceof DocumentExtractionException?ex.getMessage():"Unable to process document";log.warn("requestId={} file={} size={} durationMs={} status=FAILED reason={}",requestId,fileName,file.getSize(),elapsed,ex.getMessage());return new DocumentExtractionResponse.DocumentResult(fileName,null,names.extensionOf(fileName),file.getSize(),null,Instant.now(),0,elapsed,DocumentStatus.FAILED.name(),null,java.util.Map.of(),message);} } }
